from pathlib import Path
import json
O=Path(__file__).resolve().parents[1]; screens=json.loads((O/'manifest.json').read_text());assets=json.loads((O/'assets/manifest.json').read_text())
head='''<!doctype html><html lang="ru" data-theme="classic"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Minor · Mind Map / Design Review</title><link rel="stylesheet" href="../tokens.css"><link rel="stylesheet" href="../components/bundle.css"><link rel="stylesheet" href="gallery.css"><script src="gallery.js" defer></script></head><body>'''
body='''<header class="review-head"><div><p class="overline">MINOR AI / DESIGN REVIEW</p><h1 class="title-2">Mind Map</h1><p class="subhead secondary">30 экранов · 6 тем · Glow</p></div><a class="mn-chip" href="README.md">Описание решений</a></header><nav class="review-controls" aria-label="Настройки галереи"><label>Тема <select id="theme">'''+''.join(f'<option value="{x.lower()}">{x}</option>' for x in ['Classic','Vio','Aqua','Rosa','Cosmos','Flam'])+'''</select></label><label>Кадр <select id="device"><option value="393,852">393 × 852</option><option value="375,667">375 × 667</option><option value="430,932">430 × 932</option></select></label><label>Раздел <select id="section"><option value="all">Все экраны</option>'''+''.join(f'<option>{x}</option>' for x in dict.fromkeys(s['group'] for s in screens))+'''</select></label><a class="mn-chip" href="#assets">Ассеты</a><a class="mn-chip" href="#app-store">App Store</a><a class="mn-chip" href="qa/REPORT.md">Проверка</a></nav><main><div class="screens-grid">'''
for i,s in enumerate(screens):
    body+=f'<article class="screen-card" data-group="{s["group"]}"><div class="card-caption"><span class="caption secondary">{i+1:02d} / {s["group"]}</span><a class="label" href="screens/{s["file"]}.html" target="_blank">{s["title"]} ↗</a></div><iframe title="{s["title"]}" src="screens/{s["file"]}.html?theme=classic" loading="lazy" width="393" height="852"></iframe></article>'
body+='</div><section id="assets"><div class="asset-heading"><h2 class="title-2">Ассеты</h2><p class="subhead secondary">SVG + PNG @1x / @2x / @3x · готовые .imageset</p></div><div class="asset-grid">'
for a in assets:
    n=a['name'];body+=f'<a class="asset-card {"app-icon" if n.startswith("app-icon") else ""}" href="assets/{n}.imageset/{n}.svg" target="_blank"><div class="asset-preview"><img src="assets/{n}.imageset/{n}.svg" alt="{n}"></div><span class="label">{n}{" · выбран" if n=="app-icon-glow" else ""}</span><span class="caption secondary">{a["width"]} × {a["height"]} pt</span></a>'
body+='</div></section><section id="app-store"><div class="asset-heading"><h2 class="title-2">App Store</h2><p class="subhead secondary">5 кадров · 1290 × 2796 · PNG</p></div><div class="store-grid">'+''.join(f'<a href="app-store/{i:02d}-{n}.png" target="_blank"><img src="app-store/{i:02d}-{n}.png" alt="{n}" loading="lazy"></a>' for i,n in enumerate(['mind-map','sources','expand','chat','export'],1))+'</div></section></main><footer class="review-foot caption secondary">Локальный дизайн-прототип. Покупки, генерация и запись голоса не выполняются.</footer></body></html>'
(O/'index.html').write_text(head+body)
